"""Read-only summary of obs and must node sequences."""
import json
import re
import stat
import sys
from pathlib import Path


CHANNELS = ("obs", "must")


def reject_constant(value):
    raise ValueError(value)


def parse_json(raw):
    return json.loads(raw.decode("utf-8"), parse_constant=reject_constant)


def empty_channel():
    return {"count": 0, "first": None, "last": None, "missing": [],
            "dup": [], "next_seq": None, "unacked": None, "stale_next": None}


def collect(folder, entries, channel, bad):
    pattern = re.compile(rf"{channel}\.([0-9]{{12}})\.jsonl")
    numbered = []
    active = None
    for path in entries:
        match = pattern.fullmatch(path.name)
        if not match and path.name != f"{channel}.active.jsonl":
            continue
        if not stat.S_ISREG(path.lstat().st_mode):
            continue
        if match:
            numbered.append((int(match.group(1)), path))
        else:
            active = path
    files = [path for _, path in sorted(numbered)]
    if active is not None:
        files.append(active)

    counts = {}
    total = 0
    for path in files:
        with path.open("rb") as stream:
            for line_number, raw in enumerate(stream, 1):
                if not raw.endswith(b"\n"):
                    why = "torn"
                else:
                    try:
                        record = parse_json(raw)
                    except (ValueError, UnicodeError):
                        why = "bad_json"
                    else:
                        seq = record.get("seq") if isinstance(record, dict) else None
                        if type(seq) is not int or seq < 1:
                            why = "no_seq"
                        else:
                            counts[seq] = counts.get(seq, 0) + 1
                            total += 1
                            continue
                bad.append({"file": path.name, "line": line_number, "why": why})

    unique = sorted(counts)
    missing = [[left + 1, right - 1] for left, right in zip(unique, unique[1:])
               if right > left + 1]
    result = empty_channel()
    result.update(count=total, first=unique[0] if unique else None,
                  last=unique[-1] if unique else None, missing=missing,
                  dup=[seq for seq in unique if counts[seq] >= 2])
    return result, counts


def apply_state(folder, channels, seen, bad):
    try:
        raw = (folder / "state.json").read_bytes()
    except FileNotFoundError:
        return
    except OSError:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return
    try:
        state = parse_json(raw)
    except (ValueError, UnicodeError):
        state = None
    if not isinstance(state, dict) or not isinstance(state.get("channels"), dict):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return

    invalid = False
    for name in CHANNELS:
        info = state["channels"].get(name)
        if not isinstance(info, dict) or type(info.get("next_seq")) is not int:
            invalid = True
            continue
        if name == "must" and type(info.get("acked_upto")) is not int:
            invalid = True
            continue
        summary = channels[name]
        next_seq = info["next_seq"]
        summary["next_seq"] = next_seq
        summary["stale_next"] = (next_seq != summary["last"] + 1
                                  if summary["last"] is not None else None)
        if name == "must":
            summary["unacked"] = sum(seq > info["acked_upto"] for seq in seen[name])
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})


def summarize(folder):
    entries = list(folder.iterdir())
    bad = []
    channels = {}
    seen = {}
    for name in CHANNELS:
        channels[name], seen[name] = collect(folder, entries, name, bad)
    apply_state(folder, channels, seen, bad)
    bad.sort(key=lambda item: (item["file"], 0 if item["line"] is None else item["line"], item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        return 2
    print(json.dumps(summarize(Path(args[0])), ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
